sealed class MobileWorker:IDisposable{
 readonly Process process;
 public MobileWorker(string root,string directory,string url){var start=new ProcessStartInfo(Path.Combine(Environment.GetEnvironmentVariable("JAVA_HOME")??@"C:\Program Files\Java\jdk-21","bin","java.exe")){RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardInputEncoding=new UTF8Encoding(false),StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,UseShellExecute=false,CreateNoWindow=true};foreach(string arg in new[]{"-cp",Path.Combine(root,"artifacts","android-core-tests","classes"),"com.resumestudio.MobileInterop",Convert.ToBase64String(Encoding.UTF8.GetBytes(directory)),url})start.ArgumentList.Add(arg);process=Process.Start(start)!;process.ErrorDataReceived+=(_,e)=>{if(e.Data!=null)Console.Error.WriteLine(e.Data);};process.BeginErrorReadLine();}
 public async Task<JsonNode> Call(string method,JsonObject? payload=null){payload??=new();payload["method"]=method;await process.StandardInput.WriteLineAsync(payload.ToJsonString());await process.StandardInput.FlushAsync();string line=await process.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(100))??throw new IOException("Android worker exited");var response=JsonNode.Parse(line)!;if(!response["ok"]!.GetValue<bool>())throw new IOException(response["error"]!.GetValue<string>());return response["result"]!;}
 public void Dispose(){process.StandardInput.Close();if(!process.WaitForExit(2000))process.Kill(true);process.Dispose();}
}
sealed class Desktop:ISyncLocalStore,IDisposable{
 readonly Process process;readonly HttpClient client;public string Directory{get;}
 Desktop(Process process,HttpClient client,string directory){this.process=process;this.client=client;Directory=directory;}
 public static async Task<Desktop> Start(string root,string directory,int port){string token=Guid.NewGuid().ToString("N");var start=new ProcessStartInfo(Path.Combine(Environment.GetEnvironmentVariable("JAVA_HOME")??@"C:\Program Files\Java\jdk-21","bin","java.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string a in new[]{"-cp",Path.Combine(root,"artifacts","android-core-tests","desktop"),"com.resumestudio.Server","--port",port.ToString(),"--data",directory,"--token",token})start.ArgumentList.Add(a);var p=Process.Start(start)!;var http=new HttpClient{BaseAddress=new Uri($"http://127.0.0.1:{port}/api/")};http.DefaultRequestHeaders.Add("X-Resume-Token",token);for(int i=0;i<60;i++){try{var r=await http.GetAsync("health");if(r.IsSuccessStatusCode)return new(p,http,directory);}catch(HttpRequestException){}await Task.Delay(100);}throw new Exception("Desktop backend not ready");}
 async Task<JsonObject> ReadResponse(HttpResponseMessage response){response.EnsureSuccessStatusCode();return JsonNode.Parse(await response.Content.ReadAsStringAsync())!.AsObject();}
 public async Task Save(string path,JsonObject doc){using var r=await client.PostAsJsonAsync(path,doc);r.EnsureSuccessStatusCode();}
 public async Task<SyncLocal> ReadAsync(CancellationToken cancellationToken){using var r=await client.GetAsync("sync/extended-snapshot",cancellationToken);var data=await ReadResponse(r);return new(data["snapshot"]!.AsObject(),data["hash"]!.GetValue<string>(),DateTimeOffset.TryParse(data["modifiedAt"]?.GetValue<string>(),out var time)?time:null);}
 public async Task ValidateAsync(JsonObject snapshot,CancellationToken cancellationToken){using var r=await client.PostAsJsonAsync("sync/validate",new{snapshot},cancellationToken);r.EnsureSuccessStatusCode();}
 public async Task<SyncLocal> ApplyAsync(string expectedHash,JsonObject snapshot,CancellationToken cancellationToken){using var r=await client.PostAsJsonAsync("sync/import",new{expectedHash,snapshot},cancellationToken);var data=await ReadResponse(r);return new(data["snapshot"]!.AsObject(),data["hash"]!.GetValue<string>());}
 public void Dispose(){client.Dispose();if(!process.HasExited)process.Kill(true);process.Dispose();}
}
